import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    max_len = 1  # At least one element

    # Find the longest strictly increasing contiguous subarray
    current_len = 1
    for i in range(1, n):
        if a[i] > a[i-1]:
            current_len += 1
            if current_len > max_len:
                max_len = current_len
        else:
            current_len = 1

    # Check if we can extend by removing one element
    # Check from the end
    for i in range(n-1, 0, -1):
        if a[i] > a[i-1]:
            # Can we extend by removing a[i]?
            if i < n-1 and a[i+1] > a[i-1]:
                max_len = max(max_len, current_len + 1)
            # Can we extend by removing a[i-1]?
            if i > 1 and a[i] > a[i-2]:
                max_len = max(max_len, current_len + 1)
            break

    print(max_len)

if __name__ == "__main__":
    solve()
"}

