def is_good(vowel_count, length):
    """Check if a substring with given vowel count and length is good."""
    return vowel_count <= 2 * (length - vowel_count)

def solve(s):
    n = len(s)
    max_length = 0
    count = 0

    # Vowel set
    vowels = set("aeiouAEIOU")

    # Sliding window approach
    left = 0
    vowel_count = 0

    for right in range(n):
        # Update vowel count
        if s[right] in vowels:
            vowel_count += 1

        # Check if current window is good
        window_length = right - left + 1
        if is_good(vowel_count, window_length):
            # Update max length and count
            if window_length > max_length:
                max_length = window_length
                count = 1
            elif window_length == max_length:
                count += 1
        else:
            # Move left forward until window is good again
            while left <= right and not is_good(vowel_count, window_length):
                if s[left] in vowels:
                    vowel_count -= 1
                left += 1
            # After while loop, check if window is good
            if is_good(vowel_count, window_length):
                if window_length > max_length:
                    max_length = window_length
                    count = 1
                elif window_length == max_length:
                    count += 1

    if max_length == 0:
        return "No solution"
    else:
        return f"{max_length} {count}"

# Read input and output result
s = input().strip()
result = solve(s)
print(result)
