import sys
from collections import deque

def is_lucky(n):
    """Check if a number is lucky (only contains 4 and 7)."""
    while n > 0:
        if n % 10 not in {4, 7}:
            return False
        n //= 10
    return True

def generate_lucky_numbers(limit=10**9):
    """Generate all lucky numbers up to the given limit."""
    lucky = []
    queue = deque([4, 7])

    while queue:
        num = queue.popleft()
        if num <= limit:
            lucky.append(num)
            queue.append(num * 10 + 4)
            queue.append(num * 10 + 7)
    return sorted(lucky)

def count_lucky_in_interval(a, b, lucky):
    """Count how many lucky numbers are in [a, b]."""
    count = 0
    for lucky_num in lucky:
        if a <= lucky_num <= b:
            count += 1
    return count

def solve(pl, pr, vl, vr, k):
    lucky = generate_lucky_numbers()

    total_pairs = (pr - pl + 1) * (vr - vl + 1)
    valid_pairs = 0

    # Iterate through all pairs (p, v)
    for p in range(pl, pr + 1):
        for v in range(vl, vr + 1):
            a = min(p, v)
            b = max(p, v)
            if count_lucky_in_interval(a, b, lucky) == k:
                valid_pairs += 1

    probability = valid_pairs / total_pairs
    return probability

if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    if not data:
        exit()

    pl, pr, vl, vr, k = map(int, data)

    result = solve(pl, pr, vl, vr, k)
    print(f"{result:.15f}")
"}

