import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    s = int(next(it))

    # Map each note to its positions
    note_positions = [[] for _ in range(k + 1)]  # 1-indexed
    for i in range(n):
        for j in range(m):
            note = int(next(it))
            note_positions[note].append((i, j))

    # Song notes
    song = [int(next(it)) for _ in range(s)]

    # DP: dp[i][x][y] = maximum complexity up to position i, ending at (x, y)
    # We'll use a 2D array for the current and previous positions
    prev = {}

    # Initialize for the first note
    first_note = song[0]
    for x, y in note_positions[first_note]:
        prev[(x, y)] = 0  # No previous move, complexity is 0

    # For each subsequent note
    for i in range(1, s):
        curr = {}
        curr_note = song[i]

        # Get all positions for the current note
        for x, y in note_positions[curr_note]:
            # Try all positions from the previous note
            for (px, py), prev_complexity in prev.items():
                move_complexity = abs(x - px) + abs(y - py)
                total_complexity = prev_complexity + move_complexity

                # Update current position
                if (x, y) not in curr or curr[(x, y)] < total_complexity:
                    curr[(x, y)] = total_complexity

        # Update prev for next iteration
        prev = curr

    # Find the maximum complexity
    if prev:
        print(max(prev.values()))
    else:
        print(0)

if __name__ == "__main__":
    solve()
"}

