import sys

def is_unimodal(arr):
    """Check if an array is unimodal."""
    n = len(arr)
    if n == 1:
        return True  # Single element is trivially unimodal

    # Determine the current phase: 1=increasing, 2=constant, 3=decreasing
    current_phase = 1  # Start with strictly increasing

    for i in range(n - 1):
        if current_phase == 1:
            # Strictly increasing
            if arr[i] < arr[i + 1]:
                continue  # Still in phase 1
            elif arr[i] == arr[i + 1]:
                current_phase = 2  # Transition to constant
            else:  # arr[i] > arr[i + 1]
                current_phase = 3  # Transition to strictly decreasing
        elif current_phase == 2:
            # Constant
            if arr[i] == arr[i + 1]:
                continue  # Still in phase 2
            elif arr[i] > arr[i + 1]:
                current_phase = 3  # Transition to strictly decreasing
            else:  # arr[i] < arr[i + 1]
                return False  # Invalid transition
        else:  # current_phase == 3
            # Strictly decreasing
            if arr[i] > arr[i + 1]:
                continue  # Still in phase 3
            else:
                return False  # Invalid transition

    return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:n + 1]))

    if is_unimodal(arr):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
"}

