def is_lucky(n):
    while n > 0:
        if n % 10 not in {4, 7}:
            return False
        n //= 10
    return True

def generate_lucky_numbers():
    lucky = []
    # Generate all lucky numbers up to 10^9
    # We can generate them by considering all combinations of 4 and 7
    # for lengths 1 to 10 (since 7777777777 > 10^9)
    for length in range(1, 11):
        for bits in range(1 << length):
            num = 0
            for i in range(length):
                if bits & (1 << i):
                    num = num * 10 + 7
                else:
                    num = num * 10 + 4
            lucky.append(num)
    lucky.sort()
    return lucky

lucky = generate_lucky_numbers()

# Function to count lucky numbers in [a, b]
def count_lucky(a, b):
    left = bisect.bisect_left(lucky, a)
    right = bisect.bisect_right(lucky, b) - 1
    if left > right:
        return 0
    return right - left + 1

# Read input
pl, pr, vl, vr, k = map(int, input().split())

# Total number of pairs
total = (pr - pl + 1) * (vr - vl + 1)

# Count valid pairs
valid = 0

# For each possible p
for p in range(pl, pr + 1):
    # For each possible v
    for v in range(vl, vr + 1):
        a = min(p, v)
        b = max(p, v)
        if count_lucky(a, b) == k:
            valid += 1

# Calculate probability
probability = valid / total
print(f"{probability:.15f}")
