def compute_square_free(n):
    """Compute the square-free part of n"""
    i = 2
    while i * i <= n:
        count = 0
        while n % i == 0:
            n //= i
            count += 1
        if count % 2 == 1:
            yield i
        i += 1
    if n > 1:
        yield n


def solve():
    import sys
    input = sys.stdin.read()
    data = input.split()
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Compute square-free parts
        group_sizes = {}
        for num in a:
            # Get square-free part
            square_free = 1
            i = 2
            temp = num
            while i * i <= temp:
                count = 0
                while temp % i == 0:
                    temp //= i
                    count += 1
                if count % 2 == 1:
                    square_free *= i
                i += 1
            if temp > 1:
                square_free *= temp

            if square_free in group_sizes:
                group_sizes[square_free] += 1
            else:
