def solve():
    n = input().strip()
    if len(n) == 0:
        return

    # Convert to list of characters
    digits = list(n)

    # Find the rightmost even digit that is not the last digit
    rightmost_even_non_last = -1
    for i in range(len(digits) - 2, -1, -1):
        if int(digits[i]) % 2 == 0:
            rightmost_even_non_last = i
            break

    # Find the smallest even digit that is not the last digit
    smallest_even_non_last = float('inf')
    for i in range(len(digits) - 1):
        if int(digits[i]) % 2 == 0:
            smallest_even_non_last = min(smallest_even_non_last, i)

    if rightmost_even_non_last == -1 and smallest_even_non_last == float('inf'):
        # No even digit exists
        print(-1)
        return

    if rightmost_even_non_last != -1:
        # Swap with rightmost even that is not last
        digits[rightmost_even_non_last], digits[-1] = digits[-1], digits[rightmost_even_non_last]
    else:
        # Swap with smallest even that is not last
        digits[smallest_even_non_last], digits[-1] = digits[-1], digits[smallest_even_non_last]

    print(''.join(digits))

solve()
