        available.append([0])  # only rest
    elif a == 1:
        available.append([0, 2])  # rest or contest
    elif a == 2:
        available.append([0, 1])  # rest or sport
    elif a == 3:
        available.append([0, 1, 2])  # rest, sport, or contest

# Initialize DP
# dp[i][curr_act] = minimum rest days up to day i, where curr_act is what Vasya did on day i
# We need to track what activity we did on day i to ensure constraints with day i+1

dp = [[float('inf')] * 3 for _ in range(n)]

# Base case: day 0
for act in available[0]:
    dp[0][act] = 1 if act == 0 else 0

for i in range(1, n):
    for prev_act in range(3):
        if dp[i-1][prev_act] == float('inf'):
            continue

        for curr_act in available[i]:
            # Check constraints
            if prev_act == 1 and curr_act == 1:  # sport followed by sport
                continue
            if prev_act == 2 and curr_act == 2:  # contest followed by contest
                continue

            # Update DP
            if curr_act == 0:
                # Rest, increment rest days
                dp[i][curr_act] = min(dp[i][curr_act], dp[i-1][prev_act] + 1)
            else:
                # Not resting, no increment
                dp[i][curr_act] = min(dp[i][curr_act], dp[i-1][prev_act])

# Answer is the minimum of dp[n-1][*]
print(min(dp[n-1]))
