import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])

    count = [0] * (k + 1)
    for i in range(2, 2 + n):
        count[int(data[i])] += 1

    sets = (n + 1) // 2  # ceil(n/2)

    result = 0
    for i in range(1, k + 1):
