def count_camels(n, t):
    """Count the number of valid camel sequences."""

    # We'll use a brute-force approach with pruning
    from itertools import product

    count = 0

    # Generate all possible sequences of length n with values in [1, 2, 3, 4]
    for ys in product(range(1, 5), repeat=n):
        # Check if no segment is parallel to Ox-axis
        if any(ys[i] == ys[i+1] for i in range(n-1)):
