        # Count humps and valleys
        humps = 0
        valleys = 0
        for i in range(1, n-1):
            if ys[i-1] < ys[i] > ys[i+1]:
                humps += 1
            elif ys[i-1] > ys[i] < ys[i+1]:
                valleys += 1

        # Check if we have exactly t humps and t-1 valleys
        if humps == t and valleys == t - 1:
            count += 1

