def count_camels(n, t):
    """Count the number of valid camel sequences using DP."""

    # DP table: dp[i][humps][valleys][prev_y][prev_prev_y]
    # i: length of sequence
    # humps: number of humps
    # valleys: number of valleys
    # prev_y: last y-value
    # prev_prev_y: second-to-last y-value

    # Initialize: sequences of length 2
    dp = {}
    for prev_prev_y in range(1, 5):
        for prev_y in range(1, 5):
            if prev_prev_y == prev_y:
                continue  # No segment parallel to Ox-axis
            dp[(2, 0, 0, prev_y, prev_prev_y)] = 1

    # Build up sequences
    for length in range(3, n + 1):
        new_dp = {}
        for (i, humps, valleys, prev_y, prev_prev_y), count in dp.items():
            for next_y in range(1, 5):
                if next_y == prev_y:
                    continue  # No segment parallel to Ox-axis

                # Check if we form a hump, valley, or neither
                if prev_prev_y < prev_y and prev_y > next_y:
                    # Hump
                    new_humps = humps + 1
                    new_valleys = valleys
                elif prev_prev_y > prev_y and prev_y < next_y:
                    # Valley
                    new_humps = humps
                    new_valleys = valleys + 1
