import sys

def can_obtain(n, k, m, b):
    """Check if we can obtain sequence b from [1, 2, ..., n] using k elements per step"""
    # Calculate the number of elements needed on each side
    half_k_minus_1 = (k - 1) // 2

    for i in range(m):
        # For the smallest element in b, we only need elements greater than it
        if i == 0:
            needed_greater = max(0, half_k_minus_1)
            needed_less = 0
        elif i == m - 1:
            needed_greater = 0
            needed_less = max(0, half_k_minus_1)
        else:
            needed_greater = half_k_minus_1
            needed_less = half_k_minus_1

        # Check if we have enough elements on each side
        if b[i] - 1 < needed_less:
            return False
        if n - b[i] < needed_greater:
            return False

    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []
    for _ in range(t):
        n = int(data[idx])
        k = int(data[idx+1])
        m = int(data[idx+2])
        idx += 3

        b = list(map(int, data[idx:idx+m]))
        idx += m

        if can_obtain(n, k, m, b):
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

