import sys

def can_place(bottles, h):
    """Check if we can place the given bottles in the fridge."""
    # We need to place bottles in such a way that we minimize the number of shelves used
    # Try placing the tallest bottle first, then the next tallest either on the same level or a new level
    # We need to try both options recursively

    # Base case: if we've placed all bottles, check if the total height <= h
    if not bottles:
        return True

    # Place the tallest bottle first
    tallest = bottles[0]

    # Try placing the next tallest bottle on the same level if possible
    if len(bottles) > 1:
        second_tallest = bottles[1]
        if tallest + second_tallest <= h:
            return can_place(bottles[2:], h)

    # Try placing the next tallest bottle on a new level
    return can_place(bottles[1:], h)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    h = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Binary search on k
    low = 1
    high = n
    answer = 1

    while low <= high:
        mid = (low + high) // 2
        bottles = a[:mid]
        bottles.sort(reverse=True)

        if can_place(bottles, h):
            answer = mid
            low = mid + 1
        else:
            high = mid - 1

    print(answer)

if __name__ == "__main__":
    solve()
