# Check if a piece of size X,Y starting at (i,j) is unique
# Generate all 4 rotations of the piece
def get_rotations(piece, A, B):
    rotations = []
    # Original
    rot = ''
    for row in range(len(piece)):
        for col in range(len(piece[0])):
            rot += piece[row][col]
    rotations.append(rot)

    # 90 degrees clockwise
    rot = ''
    for col in range(len(piece[0])):
        for row in range(len(piece)-1, -1, -1):
            rot += piece[row][col]
    rotations.append(rot)

    # 180 degrees
    rot = ''
    for row in range(len(piece)-1, -1, -1):
        for col in range(len(piece[0])-1, -1, -1):
            rot += piece[row][col]
    rotations.append(rot)

    # 270 degrees clockwise
    rot = ''
    for col in range(len(piece[0])-1, -1, -1):
        for row in range(len(piece)):
            rot += piece[row][col]
    rotations.append(rot)

    return rotations

# Check if a puzzle with piece size X,Y is good
def is_good_puzzle(X, Y):
    # Check if X divides A and Y divides B
    if A % X != 0 or B % Y != 0:
        return False

    # For each piece, check if any other piece has any of its rotations
    pieces = []
    for i in range(0, A, X):
        for j in range(0, B, Y):
            # Extract the piece
            piece = []
            for row in range(i, i+X):
                piece.append(picture[row][j:j+Y])
            pieces.append(piece)

    # For each piece, check if it has any duplicate rotation
    used_rotations = set()
    for piece in pieces:
        rotations = get_rotations(piece, A, B)
        for rot in rotations:
            if rot in used_rotations:
                return False
            used_rotations.add(rot)

    return True

# Find all good puzzles
