import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    for _ in range(t):
        r = int(data[idx])
        c = int(data[idx + 1])
        idx += 2

        grid = []
        for i in range(r):
            row = data[idx]
            grid.append(row)
            idx += 1

        # Check if there are any 'A' cells
        has_A = any('A' in row for row in grid)
        if not has_A:
            print("MORTAL")
            continue

        # Count contiguous 'P' regions not adjacent to 'A'
        visited = [[False for _ in range(c)] for _ in range(r)]
        count = 0

        for i in range(r):
            for j in range(c):
                if grid[i][j] == 'P' and not visited[i][j]:
                    # Check if this 'P' region is adjacent to 'A'
                    is_adjacent_to_A = False

                    # Check all four directions
                    for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < r and 0 <= nj < c:
                            if grid[ni][nj] == 'A':
                                is_adjacent_to_A = True
                                break

                    if not is_adjacent_to_A:
                        count += 1
                        # Mark all connected 'P' cells as visited
                        stack = [(i, j)]
                        visited[i][j] = True
                        while stack:
                            x, y = stack.pop()
                            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                                nx, ny = x + dx, y + dy
                                if 0 <= nx < r and 0 <= ny < c and not visited[nx][ny] and grid[nx][ny] == 'P':
                                    visited[nx][ny] = True
                                    stack.append((nx, ny))

        print(count)

if __name__ == "__main__":
    solve()
"}

