def solve():
    n = int(input())
    a = list(map(int, input().split()))

    def max_score(arr):
        """Find the maximum score for a given array."""
        if not arr:
            return -float('inf')

        n = len(arr)
        left = [-1] * n
        right = [-1] * n

        # Nearest greater or equal to left
        stack = []
        for i in range(n):
            while stack and arr[stack[-1]] < arr[i]:
                stack.pop()
            if stack:
                left[i] = stack[-1]
            else:
                left[i] = -1
            stack.append(i)

        # Nearest greater to right (strictly greater)
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and arr[stack[-1]] <= arr[i]:
                stack.pop()
            if stack:
                right[i] = stack[-1]
            else:
                right[i] = -1
            stack.append(i)

        max_score = -float('inf')
        for i in range(n):
            # Segment where arr[i] is the maximum
            l = left[i] + 1
            r = right[i] - 1

            # Calculate sum of segment [l, r]
            sum_segment = sum(arr[l:r+1])

            # Score is sum - max
            score = sum_segment - arr[i]
            max_score = max(max_score, score)

        return max_score

    # Consider all segments
    score_all_segments = max_score(a)

    # Consider segments that exclude the global maximum
    max_val = max(a)
    idx = a.index(max_val)

    if idx > 0:
        left_part_score = max_score(a[:idx])
    else:
        left_part_score = -float('inf')

    if idx < n - 1:
        right_part_score = max_score(a[idx+1:])
    else:
        right_part_score = -float('inf')

    score_exclude_max = max(left_part_score, right_part_score)

    final_score = max(score_all_segments, score_exclude_max)

    print(final_score)

