def count_occurrences(text, pattern):
    """Count the number of occurrences of pattern in text."""
    count = 0
    start = 0
    while True:
        start = text.find(pattern, start)
        if start == -1:
            break
        count += 1
        start += 1  # Move past this occurrence
    return count

