import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    s = int(next(it))

    # Read the grid
    grid = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        grid.append(row)

    # Read the song
    song = [int(next(it)) for _ in range(s)]

    # For each note, find all (string, fret) pairs that produce it
    note_positions = {}
    for i in range(n):
        for j in range(m):
            note = grid[i][j]
            if note not in note_positions:
                note_positions[note] = []
            note_positions[note].append((i, j))

    # Initialize DP
    # dp[i][x][y] = maximum complexity up to note i, ending at (x, y)
    # We'll use a list of dictionaries for efficiency
    prev = {}

    # Start with the first note
    for (x, y) in note_positions[song[0]]:
        prev[(x, y)] = 0  # No previous move, complexity is 0

    # Iterate through the rest of the notes
    for i in range(1, s):
        curr = {}
        curr_note = song[i]

        for (x, y) in note_positions[curr_note]:
            # Try all previous positions
            for (p, q), max_complexity in prev.items():
                complexity = abs(x - p) + abs(y - q)
                new_max = max(max_complexity, complexity)

                if (x, y) not in curr or new_max > curr[(x, y)]:
                    curr[(x, y)] = new_max

        prev = curr

    if prev:
        print(max(prev.values()))
    else:
        print(0)

if __name__ == "__main__":
    solve()
