        # Check if current floor is open
        if s not in closed:
            print(0)
            continue

        # Find closest open floor below s
        dist_below = None
        for i in range(s - 1, 0, -1):
            if i not in closed:
                dist_below = s - i
                break

        # Find closest open floor above s
        dist_above = None
        for i in range(s + 1, n + 1):
            if i not in closed:
                dist_above = i - s
                break

        # Answer is the minimum of the two
        if dist_below is not None and dist_above is not None:
