            if is_good_puzzle(X, Y):
                good_count += 1

                area = X * Y
                if area < min_area or (area == min_area and X < min_X):
                    min_area = area
                    min_X = X
                    min_Y = Y

    print(good_count)
    print(min_X, min_Y)

