        """Extract piece from (x1, y1) to (x2, y2)"""
        piece = []
        for i in range(x1, x2 + 1):
            row = ""
            for j in range(y1, y2 + 1):
                row += grid[i][j]
            piece.append(row)
        return piece

    def rotate(piece, clockwise=1):
        """Rotate piece 90° clockwise"""
        if clockwise == 1:
            return [''.join(row) for row in zip(*piece[::-1])]
        else:  # 270° clockwise (or 90° counter-clockwise)
            return [''.join(row[::-1]) for row in zip(*piece)]

    def is_good_puzzle(X, Y):
        pieces = []
        for i in range(0, A, X):
            for j in range(0, B, Y):
                piece = get_piece(grid, i, j, i + X - 1, j + Y - 1)
                pieces.append(piece)

        # Check all pairs of pieces
        for i in range(len(pieces)):
            for j in range(i + 1, len(pieces)):
                p1 = pieces[i]
                p2 = pieces[j]

                # Check if any rotation of p1 matches any rotation of p2
                for rot1 in range(4):
                    rotated1 = p1
                    if rot1 == 1:
                        rotated1 = rotate(p1)
                    elif rot1 == 2:
                        rotated1 = rotate(p1, 1)
                    elif rot1 == 3:
                        rotated1 = rotate(p1, 2)

                    for rot2 in range(4):
                        rotated2 = p2
                        if rot2 == 1:
                            rotated2 = rotate(p2)
                        elif rot2 == 2:
                            rotated2 = rotate(p2, 1)
                        elif rot2 == 3:
                            rotated2 = rotate(p2, 2)

                        if rotated1 == rotated2:
                            return False

        return True

    good_count = 0
    min_area = float('inf')
    min_X = None
    min_Y = None

    for X in range(1, A + 1):
        if A % X != 0:
            continue
        for Y in range(1, B + 1):
            if B % Y != 0:
                continue

            if is_good_puzzle(X, Y):
                good_count += 1

                area = X * Y
                if area < min_area or (area == min_area and X < min_X):
                    min_area = area
                    min_X = X
                    min_Y = Y

    print(good_count)
    print(min_X, min_Y)

