import sys

def square_free_part(x):
    """Return the square-free part of x."""
    if x == 0:
        return 0

    # Factor out all squares
    res = 1
    i = 2
    while i * i <= x:
        if x % i == 0:
            count = 0
            while x % i == 0:
                x //= i
                count += 1
            # If count is odd, include one factor of i
            if count % 2 == 1:
                res *= i
        i += 1

    # If remaining x > 1, it's a prime factor with exponent 1
    if x > 1:
        res *= x

    return res

