import sys

def solve():
    # Read input
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    # Read grid
    grid = []
    for _ in range(4):
        row = [int(next(it)) for _ in range(n)]
        grid.append(row)

    # Find car positions and target spots
    car_positions = {}
    target_spots = {}

    for car in range(1, k + 1):
        # Find car in rows 2 and 3 (0-indexed rows 1 and 2)
        for r in range(1, 3):
            for c in range(n):
                if grid[r][c] == car:
                    car_positions[car] = (r, c)
                    break
            else:
                continue
            break

        # Find target spot in rows 1 and 4 (0-indexed rows 0 and 3)
        for r in range(0, 4, 2):
            for c in range(n):
                if grid[r][c] == car:
                    target_spots[car] = (r, c)
                    break
            else:
                continue
            break

    # List of cars that need to move
    cars_to_move = [car for car in range(1, k + 1) if car_positions[car] != target_spots[car]]

    moves = []

    # Try to move cars in a systematic way
    for car in range(1, k + 1):
        pos = car_positions[car]
        target = target_spots[car]

        if pos == target:
            continue

        # Move car to its target spot
        r1, c1 = pos
        r2, c2 = target

        # If target is empty, move directly
        if grid[r2][c2] == 0:
            moves.append(f"{car} {r2 + 1} {c2 + 1}")
            grid[r2][c2] = car
            grid[r1][c1] = 0

        # If target is occupied, we need to move the occupying car out of the way
        else:
            # Find the car that's in the target spot
            occupying_car = grid[r2][c2]

            # Move occupying car out of the way (to the right if possible)
            for c in range(c2 + 1, n):
                if grid[r2][c] == 0:
                    moves.append(f"{occupying_car} {r2 + 1} {c + 1}")
                    grid[r2][c] = occupying_car
                    grid[r2][c2] = 0
                    break

            # Now move our car to its target spot
            moves.append(f"{car} {r2 + 1} {c2 + 1}")
            grid[r2][c2] = car
            grid[r1][c1] = 0

    # Check if we exceeded the move limit
    if len(moves) > 20000:
        print(-1)
    else:
        print(len(moves))
        for move in moves:
            print(move)

if __name__ == "__main__":
    solve()
"}

