    start = None
    exit_pos = None
    for i in range(n):
        for j in range(m):
            if maze[i][j] == 'S':
                start = (i, j)
            elif maze[i][j] == 'E':
                exit_pos = (i, j)

    s = input().strip()

    # Get unique digits in the instruction string
    unique_digits = set(s)

    # Directions: 0-up, 1-right, 2-down, 3-left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Count valid mappings
    count = 0

    # Generate all permutations of directions for the unique digits
    from itertools import permutations

    for perm in permutations(directions, len(unique_digits)):
        # Map each unique digit to a direction
        digit_to_dir = {digit: perm[i] for i, digit in enumerate(unique_digits)}

        # Simulate the robot
        r, c = start
        reached_exit = False
        for ch in s:
