import sys

def is_achievable(a, n, w, m, H):
    """Check if we can make all flowers at least H tall"""
    needs = [max(0, H - a[i]) for i in range(n)]
    blocks = 0

    i = 0
    while i < n:
        if needs[i] > 0:
            # Need to water starting at i
            blocks += 1
            if blocks > m:
                return False
            # Water w contiguous flowers starting at i
            for j in range(i, min(i + w, n)):
                needs[j] -= 1
            i += 1
        else:
            i += 1

    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    w = int(data[2])
    a = list(map(int, data[3:3+n]))

    # Binary search on H
    left = min(a)
    right = left + m

    while left < right:
        mid = (left + right + 1) // 2
        if is_achievable(a, n, w, m, mid):
            left = mid
        else:
            right = mid - 1

    print(left)

if __name__ == "__main__":
    solve()
